1: import React from 'react';
2: import type { ChatMessage } from '../../types/chat';
3: import { Copy, ThumbsUp, ThumbsDown, Maximize2 } from 'lucide-react';
4: import { ChatImageGallery } from './ChatImageGallery';
5: import { AgentResponse } from './AgentResponse';
6: import { SubagentActivity } from './SubagentActivity';
7: import { MarkdownContent } from '../common/MarkdownContent';
8: import { TokenUsageTrigger } from './TokenUsageTrigger';
9: import { formatMessageTimestampSeconds } from '../../features/chat/transcriptMessages';
10: import styles from './ChatWorkspace.module.css';
11: 
12: interface AssistantMessageItemProps {
13:   msg: ChatMessage;
14:   tokenUsageActive: boolean;
15:   onOpenTokenUsage: (messageId: string) => void;
16: }
17: 
18: export const AssistantMessageItem: React.FC<AssistantMessageItemProps> = ({
19:   msg,
20:   tokenUsageActive,
21:   onOpenTokenUsage,
22: }) => {
23:   const isGenerating = msg.status === undefined && msg.elapsedTime === undefined;
24:   const elapsedSec = msg.elapsedTime !== undefined
25:     ? msg.elapsedTime
26:     : (isGenerating && (msg.startTime || msg.createdAt)
27:       ? Math.max(1, Math.floor((Date.now() - (msg.startTime || msg.createdAt)) / 1000))
28:       : undefined);
29: 
30:   const hasBlocks = Boolean(msg.blocks && msg.blocks.length > 0);
31:   const copyText = msg.content || (msg.blocks
32:     ? msg.blocks.filter((b) => b.kind === 'text').map((b) => b.content || '').join('\n\n')
33:     : '');
34: 
35:   const handleCopy = () => {
36:     if (copyText) {
37:       navigator.clipboard.writeText(copyText);
38:     }
39:   };
40: 
41:   return (
42:     <div className={styles.assistantMessage}>
43:       {/* Agent 响应过程区：交错时间线（思考、过程/结论正文、默认折叠工具组）或旧记录折叠面板 */}
44:       <AgentResponse
45:         msg={msg}
46:         isGenerating={isGenerating}
47:         elapsedSeconds={elapsedSec}
48:         acceptanceReportClassName={styles.acceptanceReport}
49:       />
50: 
51:       <SubagentActivity progress={msg.subagentProgress || []} />
52: 
53:       {/* 兼容旧消息结构：未携带 blocks 时在底部渲染回答正文 */}
54:       {!hasBlocks && (
55:         msg.content?.startsWith('## 验收报告') ? (
56:           <article className={styles.acceptanceReport}>
57:             <MarkdownContent content={msg.content} />
58:           </article>
59:         ) : (
60:           msg.content && <MarkdownContent content={msg.content} />
61:         )
62:       )}
63: 
64:       <ChatImageGallery images={msg.images} />
65: 
66:       {(msg.status === 'CANCELLED' || msg.status === 'FAILED') && (
67:         <div
68:           className={`${styles.terminalStatus} ${msg.status === 'FAILED' ? styles.failedStatus : ''}`}
69:           role={msg.status === 'FAILED' ? 'alert' : 'status'}
70:         >
71:           {msg.status === 'CANCELLED'
72:             ? '已停止生成'
73:             : (msg.failureReason || '生成失败，请重试。')}
74:         </div>
75:       )}
76: 
77:       {(copyText || msg.usage || msg.proactive) && (() => {
78:         const proactiveTimestamp = msg.proactive ? formatMessageTimestampSeconds(msg.createdAt) : '';
79:         if (!copyText && !msg.usage && !proactiveTimestamp) return null;
80:         return (
81:           <div className={styles.messageFooter}>
82:             {/* 消息底部操作工具栏：复制、赞、踩、全屏/分享 */}
83:             {copyText && (
84:               <div className={styles.messageActions}>
85:                 <button className={styles.actionBtn} title="复制内容" aria-label="复制内容" onClick={handleCopy}>
86:                   <Copy size={14} />
87:                 </button>
88:                 <button className={styles.actionBtn} title="即将推出" aria-label="赞（即将推出）" disabled>
89:                   <ThumbsUp size={14} />
90:                 </button>
91:                 <button className={styles.actionBtn} title="即将推出" aria-label="踩（即将推出）" disabled>
92:                   <ThumbsDown size={14} />
93:                 </button>
94:                 <button className={styles.actionBtn} title="即将推出" aria-label="全屏/扩展（即将推出）" disabled>
95:                   <Maximize2 size={14} />
96:                 </button>
97:               </div>
98:             )}
99:             <TokenUsageTrigger
100:               usage={msg.usage}
101:               active={tokenUsageActive}
102:               onOpen={() => onOpenTokenUsage(msg.id)}
103:             />
104:             {proactiveTimestamp && (
105:               <time
106:                 className={styles.proactiveTime}
107:                 dateTime={new Date(msg.createdAt).toISOString()}
108:                 title={`推送时间：${proactiveTimestamp}`}
109:               >
110:                 {proactiveTimestamp}
111:               </time>
112:             )}
113:           </div>
114:         );
115:       })()}
116:     </div>
117:   );
118: };

