1: import React, { useMemo, useState } from 'react';
2: import { ChevronDown, Database, FileCode2, FileText, Search, Terminal } from 'lucide-react';
3: import type { ChatMessage, MessageBlock, ToolDefinition, TraceNode, ToolExecution } from '../../types/chat';
4: import {
5:   formatElapsedDuration,
6:   splitProcessAndFinalBlocks,
7:   splitReasoningSentences,
8:   toolExecutionToTraceNode,
9: } from '../../features/chat/messageBlocks';
10: import { MarkdownContent } from '../common/MarkdownContent';
11: import { NestedReasoningBlock } from './NestedReasoningBlock';
12: import { ThinkingState } from './ThinkingState';
13: import { ToolGroupBlock } from './ToolGroupBlock';
14: import thinkingStyles from './ThinkingState.module.css';
15: import styles from './AgentResponse.module.css';
16: 
17: /** 默认工具展示注册表 */
18: export const DEFAULT_TOOL_REGISTRY: Record<string, ToolDefinition> = {
19:   read_file: {
20:     name: 'read_file',
21:     label: '读取',
22:     icon: FileText,
23:     monoChip: true,
24:   },
25:   edit_file: {
26:     name: 'edit_file',
27:     label: '编辑',
28:     icon: FileCode2,
29:     iconClassName: '#d97706',
30:     monoChip: true,
31:   },
32:   execute_command: {
33:     name: 'execute_command',
34:     label: '运行',
35:     icon: Terminal,
36:     iconClassName: '#7c3aed',
37:     monoChip: true,
38:   },
39:   search_web: {
40:     name: 'search_web',
41:     label: '搜索',
42:     icon: Search,
43:   },
44:   query_database: {
45:     name: 'query_database',
46:     label: 'SQL 查询',
47:     icon: Database,
48:     iconClassName: '#059669',
49:     monoChip: true,
50:   },
51: };
52: 
53: function resolveToolLabel(toolName: string): string | undefined {
54:   const toolDef = DEFAULT_TOOL_REGISTRY[toolName];
55:   return typeof toolDef?.label === 'function' ? toolDef.label(undefined) : toolDef?.label;
56: }
57: 
58: function toTraceNodes(
59:   reasoning: string | undefined,
60:   tools: ToolExecution[] | undefined,
61:   elapsedSeconds: number | undefined,
62:   isGenerating: boolean
63: ): TraceNode[] {
64:   const nodes: TraceNode[] = [];
65: 
66:   if (reasoning && reasoning.trim()) {
67:     nodes.push({
68:       type: 'reasoning',
69:       sentences: splitReasoningSentences(reasoning, !isGenerating),
70:       durationSeconds: elapsedSeconds,
71:     });
72:   }
73: 
74:   (tools || []).forEach((tool) => {
75:     nodes.push(toolExecutionToTraceNode(tool, resolveToolLabel));
76:   });
77: 
78:   return nodes;
79: }
80: 
81: export interface AgentResponseProps {
82:   msg: ChatMessage;
83:   isGenerating: boolean;
84:   elapsedSeconds?: number;
85:   acceptanceReportClassName?: string;
86: }
87: 
88: function renderTimelineBlock(
89:   block: MessageBlock,
90:   index: number,
91:   options: {
92:     isLast: boolean;
93:     isGenerating: boolean;
94:     thinkingDurationSeconds?: number;
95:     acceptanceReportClassName?: string;
96:   },
97: ): React.ReactNode {
98:   if (block.kind === 'thinking') {
99:     const raw = block.content || '';
100:     if (!raw.trim()) return null;
101:     const isActive = options.isGenerating && options.isLast;
102:     const parsed = splitReasoningSentences(raw, !isActive);
103:     const sentences = parsed.length > 0 ? parsed : [raw.trim()];
104:     return (
105:       <NestedReasoningBlock
106:         key={block.id || index}
107:         sentences={sentences}
108:         isActive={isActive}
109:         isFinished={!isActive}
110:         durationSeconds={options.thinkingDurationSeconds}
111:         collapseWhileActive
112:       />
113:     );
114:   }
115: 
116:   if (block.kind === 'tool_group') {
117:     if (!block.tools || block.tools.length === 0) return null;
118:     return (
119:       <ToolGroupBlock
120:         key={block.id || index}
121:         tools={block.tools}
122:         isGenerating={options.isGenerating}
123:         resolveToolLabel={resolveToolLabel}
124:       />
125:     );
126:   }
127: 
128:   const text = block.content || '';
129:   if (!text.trim()) return null;
130:   if (options.isLast && options.acceptanceReportClassName && text.startsWith('## 验收报告')) {
131:     return (
132:       <article key={block.id || index} className={options.acceptanceReportClassName}>
133:         <MarkdownContent content={text} />
134:       </article>
135:     );
136:   }
137:   return <MarkdownContent key={block.id || index} content={text} />;
138: }
139: 
140: /**
141:  * Agent 响应过程区：流式进行中实时呈现 ReAct 交错时间线；输出完成后将思考与工具链统一折叠为
142:  * “用时 X 秒 >”，仅保留最终结论展示在下方（点击总耗时可展开查看完整交错过程）。
143:  */
144: export const AgentResponse: React.FC<AgentResponseProps> = ({
145:   msg,
146:   isGenerating,
147:   elapsedSeconds,
148:   acceptanceReportClassName,
149: }) => {
150:   const [processExpanded, setProcessExpanded] = useState(false);
151:   const blocks = msg.blocks;
152:   const hasBlocks = Boolean(blocks && blocks.length > 0);
153:   const trace = useMemo(
154:     () => (hasBlocks ? [] : toTraceNodes(msg.reasoning, msg.tools, elapsedSeconds, isGenerating)),
155:     [hasBlocks, msg.reasoning, msg.tools, elapsedSeconds, isGenerating]
156:   );
157: 
158:   if (hasBlocks && blocks) {
159:     const thinkingCount = blocks.filter((b) => b.kind === 'thinking').length;
160:     const thinkingDuration = thinkingCount === 1 ? elapsedSeconds : undefined;
161: 
162:     if (isGenerating) {
163:       return (
164:         <div className={styles.container}>
165:           {blocks.map((block, index) =>
166:             renderTimelineBlock(block, index, {
167:               isLast: index === blocks.length - 1,
168:               isGenerating: true,
169:               thinkingDurationSeconds: thinkingDuration,
170:               acceptanceReportClassName,
171:             }),
172:           )}
173:         </div>
174:       );
175:     }
176: 
177:     const { processBlocks, finalTextBlock } = splitProcessAndFinalBlocks(blocks);
178:     return (
179:       <div className={styles.container}>
180:         {processBlocks.length > 0 && (
181:           <div className={thinkingStyles.container}>
182:             <button
183:               type="button"
184:               aria-expanded={processExpanded}
185:               onClick={() => setProcessExpanded((prev) => !prev)}
186:               className={thinkingStyles.masterTrigger}
187:             >
188:               <span className={thinkingStyles.masterLabel}>
189:                 <span className={thinkingStyles.elapsedText}>
190:                   {formatElapsedDuration(elapsedSeconds)}
191:                 </span>
192:               </span>
193:               <ChevronDown
194:                 aria-hidden="true"
195:                 className={`${thinkingStyles.chevron} ${processExpanded ? thinkingStyles.chevronOpen : ''}`}
196:               />
197:             </button>
198: 
199:             <div className={`${thinkingStyles.channel} ${processExpanded ? thinkingStyles.channelOpen : ''}`}>
200:               <div className={thinkingStyles.channelInner}>
201:                 <div className={thinkingStyles.timeline}>
202:                   {processBlocks.map((block, index) =>
203:                     renderTimelineBlock(block, index, {
204:                       isLast: false,
205:                       isGenerating: false,
206:                       thinkingDurationSeconds: thinkingDuration,
207:                     }),
208:                   )}
209:                 </div>
210:               </div>
211:             </div>
212:           </div>
213:         )}
214: 
215:         {finalTextBlock &&
216:           renderTimelineBlock(finalTextBlock, blocks.length - 1, {
217:             isLast: true,
218:             isGenerating: false,
219:             acceptanceReportClassName,
220:           })}
221:       </div>
222:     );
223:   }
224: 
225:   if (!isGenerating && trace.length === 0) return null;
226: 
227:   return (
228:     <div className={styles.container}>
229:       <ThinkingState
230:         nodes={trace}
231:         tools={DEFAULT_TOOL_REGISTRY}
232:         isWorking={isGenerating}
233:         elapsedSeconds={elapsedSeconds}
234:         workingLabel="正在处理"
235:         defaultExpanded={false}
236:       />
237:     </div>
238:   );
239: };

