1: import React, { useCallback, useEffect, useRef, useState } from 'react';
2: import { Brain, ChevronDown } from 'lucide-react';
3: import styles from './NestedReasoningBlock.module.css';
4: 
5: const SENT_H = 46;
6: const GAP = 8;
7: const MAX_H = 184;
8: const EXPANDED_MAX_H = 240;
9: const FADE = 18;
10: 
11: export interface NestedReasoningBlockProps {
12:   sentences: string[];
13:   isActive: boolean;
14:   isFinished: boolean;
15:   durationSeconds?: number;
16:   /** 为 true 时即使正在思考也默认折叠，由用户点击手动展开。 */
17:   collapseWhileActive?: boolean;
18: }
19: 
20: /**
21:  * 嵌套推理块：流式展示思考句子，默认可折叠并通过点击手动展开。
22:  */
23: export const NestedReasoningBlock: React.FC<NestedReasoningBlockProps> = ({
24:   sentences,
25:   isActive,
26:   isFinished,
27:   durationSeconds,
28:   collapseWhileActive = false,
29: }) => {
30:   const [manualOpen, setManualOpen] = useState(false);
31:   const [fade, setFade] = useState({ top: false, bottom: false });
32:   const viewportRef = useRef<HTMLDivElement>(null);
33: 
34:   const canToggle = isFinished || collapseWhileActive;
35:   const expanded = collapseWhileActive
36:     ? manualOpen
37:     : (isFinished ? manualOpen : isActive);
38:   const count = sentences.length;
39:   const contentH = count > 0 ? count * SENT_H + (count - 1) * GAP : 0;
40:   const capped = contentH > MAX_H;
41:   const viewH = capped ? MAX_H : contentH;
42:   const scrollable = (isFinished || collapseWhileActive) && expanded;
43:   const translate = scrollable ? 0 : capped ? MAX_H - FADE - contentH : 0;
44: 
45:   const showTop = scrollable ? fade.top : capped;
46:   const showBottom = scrollable ? fade.bottom : capped;
47:   const useMask = scrollable ? (showTop || showBottom) : capped;
48: 
49:   const mask = useMask
50:     ? `linear-gradient(to bottom, transparent 0, #000 ${showTop ? FADE : 0}px, #000 calc(100% - ${
51:         showBottom ? FADE : 0
52:       }px), transparent 100%)`
53:     : 'none';
54: 
55:   const syncFade = useCallback(() => {
56:     const el = viewportRef.current;
57:     if (!el) return;
58:     setFade({
59:       top: el.scrollTop > 1,
60:       bottom: el.scrollTop + el.clientHeight < el.scrollHeight - 1,
61:     });
62:   }, []);
63: 
64:   useEffect(() => {
65:     if (scrollable) syncFade();
66:   }, [scrollable, sentences, syncFade]);
67: 
68:   return (
69:     <div className={styles.container}>
70:       <button
71:         type="button"
72:         disabled={!canToggle}
73:         aria-expanded={expanded}
74:         onClick={() => canToggle && setManualOpen((v) => !v)}
75:         className={`${styles.trigger} ${canToggle ? styles.triggerClickable : ''}`}
76:       >
77:         <span className={styles.iconWrap}>
78:           <Brain className={`${styles.brain} ${canToggle ? styles.brainHoverable : ''} ${manualOpen ? styles.brainHidden : ''}`} aria-hidden="true" />
79:           {canToggle && (
80:             <ChevronDown
81:               className={`${styles.chevron} ${manualOpen ? styles.chevronOpen : ''}`}
82:               aria-hidden="true"
83:             />
84:           )}
85:         </span>
86: 
87:         <span className={styles.label}>
88:           {isFinished ? (
89:             <span className={styles.finishedLabel}>
90:               {durationSeconds !== undefined ? (
91:                 <>
92:                   思考 <span className={styles.duration}>{durationSeconds}s</span>
93:                 </>
94:               ) : (
95:                 '已思考'
96:               )}
97:             </span>
98:           ) : (
99:             <span className={styles.thinkingShimmer}>思考中…</span>
100:           )}
101:         </span>
102:       </button>
103: 
104:       <div className={`${styles.channel} ${expanded ? styles.channelOpen : ''}`}>
105:         <div className={styles.channelInner}>
106:           <div className={styles.timeline}>
107:             <div
108:               ref={viewportRef}
109:               className={`${styles.viewport} ${scrollable ? styles.scrollable : ''}`}
110:               style={{
111:                 ...(scrollable ? { maxHeight: `${EXPANDED_MAX_H}px` } : { height: `${viewH}px` }),
112:                 WebkitMaskImage: mask,
113:                 maskImage: mask,
114:               }}
115:               onScroll={scrollable ? syncFade : undefined}
116:             >
117:               <div
118:                 className={`${styles.sentenceList} ${scrollable ? styles.sentenceListExpanded : ''}`}
119:                 style={scrollable ? undefined : { transform: `translateY(${translate}px)` }}
120:               >
121:                 {sentences.slice(0, count).map((line, i) => (
122:                   <p key={i} className={`${styles.sentence} ${scrollable ? styles.sentenceExpanded : ''}`}>
123:                     {line}
124:                   </p>
125:                 ))}
126:               </div>
127:             </div>
128:           </div>
129:         </div>
130:       </div>
131:     </div>
132:   );
133: };

