30: function createBlockId(msg: ChatMessage, blocks: MessageBlock[]): string {
31:   return `${msg.id}_b_${blocks.length}`;
32: }
33: 
34: function appendSequentialText(
35:   msg: ChatMessage,
36:   kind: 'text' | 'thinking',
37:   chunk: string,
38: ): MessageBlock[] | undefined {
39:   if (!chunk) return msg.blocks;
40:   const blocks = msg.blocks ? [...msg.blocks] : [];
41:   const last = blocks[blocks.length - 1];
42:   if (last && last.kind === kind) {
43:     blocks[blocks.length - 1] = {
44:       ...last,
45:       content: (last.content || '') + chunk,
46:     };
47:     return blocks;
48:   }
49:   if (!chunk.trim()) {
50:     return msg.blocks;
51:   }
52:   blocks.push({
53:     id: createBlockId(msg, blocks),
54:     kind,
55:     content: chunk,
56:   });
57:   return blocks;
58: }
59: 
60: /** 向助手消息追加流式正文增量，同时按时序维护交错时间线 `blocks`。 */
61: export function appendTextBlock(msg: ChatMessage, chunk: string): ChatMessage {
62:   return {
63:     ...msg,
64:     content: msg.content + chunk,
65:     blocks: appendSequentialText(msg, 'text', chunk),
66:   };
67: }
68: 
69: /** 向助手消息追加流式思考增量，同时按时序维护交错时间线 `blocks`。 */
70: export function appendThinkingBlock(msg: ChatMessage, chunk: string): ChatMessage {
71:   return {
72:     ...msg,
73:     reasoning: (msg.reasoning || '') + chunk,
74:     blocks: appendSequentialText(msg, 'thinking', chunk),
75:   };
76: }
77: 
78: function upsertToolInList(
79:   list: ToolExecution[],
80:   targetId: string,
81:   toolName: string,
82:   command: string,
83: ): ToolExecution[] {
84:   const next = [...list];
85:   const idx = next.findIndex((t) => t.toolCallId === targetId);
86:   if (idx >= 0) {
87:     next[idx] = {
88:       ...next[idx],
89:       toolName: toolName || next[idx].toolName,
90:       command: command || next[idx].command,
91:     };
92:     return next;
93:   }
94:   next.push({
95:     toolCallId: targetId,
96:     toolName: toolName || 'tool',
97:     command,
98:     status: 'running',
99:   });
100:   return next;
101: }
102: 
103: /** 记录工具调用发起或参数补全；同一步连续调用合并入同一 `tool_group` 块。 */
104: export function upsertToolCallBlock(
105:   msg: ChatMessage,
