296: export function formatElapsedDuration(totalSeconds?: number): string {
297:   const safe = Math.max(0, Math.round(totalSeconds ?? 0));
298:   if (safe < 60) return `用时 ${safe} 秒`;
299:   const hours = Math.floor(safe / 3600);
300:   const minutes = Math.floor((safe % 3600) / 60);
301:   const seconds = safe % 60;
302:   if (hours > 0) {
303:     return seconds > 0
304:       ? `用时 ${hours}小时 ${minutes}分钟 ${seconds}秒`
305:       : `用时 ${hours}小时 ${minutes}分钟`;
306:   }
307:   return seconds > 0 ? `用时 ${minutes}分钟 ${seconds}秒` : `用时 ${minutes}分钟`;
