16: @Component
17: public class ActiveAgentRunRegistry {
18: 
19:     private final ConcurrentMap<String, ActiveRun> runs = new ConcurrentHashMap<>();
20:     private final ConcurrentMap<SessionKey, String> sessionRuns = new ConcurrentHashMap<>();
21: 
22:     /** 注册新运行；同一用户会话同时只允许一轮。 */
23:     public void register(String userId, String sessionId, AgentStreamSession session) {
24:         Objects.requireNonNull(session, "session");
25:         SessionKey key = new SessionKey(userId, sessionId);
26:         String existingRunId = sessionRuns.putIfAbsent(key, session.runId());
27:         if (existingRunId != null) {
28:             throw new IllegalArgumentException("当前会话已有正在运行的回复");
29:         }
30:         ActiveRun previous = runs.putIfAbsent(session.runId(), new ActiveRun(userId, sessionId, session));
31:         if (previous != null) {
32:             sessionRuns.remove(key, session.runId());
33:             throw new IllegalArgumentException("runId 已被使用");
34:         }
35:     }
36: 
37:     /** 取消精确运行；会话或用户不匹配时按未找到处理。 */
38:     public CancelResult cancel(String userId, String sessionId, String runId) {
39:         ActiveRun active = runs.get(runId);
40:         if (active == null
41:                 || !Objects.equals(active.userId(), userId)
42:                 || !Objects.equals(active.sessionId(), sessionId)) {
43:             return new CancelResult(runId, false, "NOT_FOUND");
44:         }
45:         boolean accepted = active.session().requestCancellation();
46:         return new CancelResult(runId, accepted, "CANCELLING");
47:     }
48: 
49:     /** 仅由原运行句柄解注册，避免迟到的 finally 删除后续运行。 */
50:     public void unregister(String userId, String sessionId, AgentStreamSession session) {
51:         runs.remove(session.runId(), new ActiveRun(userId, sessionId, session));
52:         sessionRuns.remove(new SessionKey(userId, sessionId), session.runId());
53:     }
54: 
55:     /** 发出取消请求；真正停稳由重置租约等待确认。 */
56:     public void cancelAll(String userId) {
57:         runs.values().stream().filter(run -> run.userId().equals(userId))
58:                 .forEach(run -> run.session().requestCancellation());
59:     }
60: 
61:     public record CancelResult(String runId, boolean accepted, String status) {}
62: 
63:     private record ActiveRun(String userId, String sessionId, AgentStreamSession session) {}
64: 
65:     private record SessionKey(String userId, String sessionId) {}
66: }

