/** 生成阶段工具组的单行中文折叠摘要（如“已读取文件、编辑文件、运行命令（5 项）”）。 */
export function formatToolGroupSummary(
  tools: ToolExecution[],
  isGenerating: boolean,
  options?: { analyzingAfterTools?: boolean },
): ToolGroupSummary {
  const runningTools = isGenerating && tools.some((t) => t.status === 'running');
